#!/usr/bin/env python3
"""Builds podcast_script_lar{,_fr,_de,_lb}.md from build/lar_src/<lang>.txt
(body turns: 'A: text' = Anna, 'T: text' = Tom, 'C: text' = Anna's closing line, followed by the standard outro)
+ the standard Biergerpakt intro/outro taken from the kjt scripts. Edit the .txt files and re-run; do not edit the .md."""
KEY = "lar"
HEAD = {
 "en": ('# Podcast Script — "Luxembourg Air Rescue – Rescue Helicopters and Repatriation"', "**Part of the Biergerpakt programme**", "**Hosts:** Anna (woman) and Tom (man)", "**Length:** about {MIN} minutes — spoken slowly, in simple English"),
 "fr": ("# Script du podcast — « Luxembourg Air Rescue – hélicoptères de secours et rapatriement »", "**Dans le cadre du programme Biergerpakt**", "**Animateurs :** Anna (femme) et Tom (homme)", "**Durée :** environ {MIN} minutes — parlé lentement, dans un français simple"),
 "de": ("# Podcast-Skript — „Luxembourg Air Rescue – Rettungshubschrauber und Rückholung“", "**Teil des Biergerpakt-Programms**", "**Moderation:** Anna (Frau) und Tom (Mann)", "**Länge:** etwa {MIN} Minuten — langsam gesprochen, in einfachem Deutsch"),
 "lb": ("# Podcast-Skript — „Luxembourg Air Rescue – Rettungshelikopteren a Rapatriement“", "**Deel vum Biergerpakt-Programm**", "**Moderatioun:** Anna (Fra) an Tom (Mann)", "**Längt:** ongeféier {MIN} Minutten — lues geschwat, an engem einfache Lëtzebuergesch"),
}
MIN = {"en": 10, "fr": 10, "de": 11, "lb": 10}   # EN 10:16, FR 9:37, DE 10:49 (26 Nov 2026)
OUTRO_START = {"en": "This podcast is part of the Biergerpakt, a programme", "fr": "Ce podcast fait partie du Biergerpakt, un programme",
               "de": "Dieser Podcast ist Teil des Biergerpakt, ein Programm", "lb": "Dëse Podcast ass Deel vum Biergerpakt, engem Programm"}
SOURCES = {
 "en": "*Sources: lar.lu (Luxembourg Air Rescue A.s.b.l.), consulted on 26 November 2026 in English, with the French and German home pages and the French membership FAQ for the official terms — home page; \"About us\" (non-profit association founded in 1988 by a group of firefighters; private organisation of public utility; alert centre open day and night); \"History\" (agreements with Saarland and Rhineland-Palatinate; hoist training with the fire and rescue services); \"Air rescue – Helicopters\" (emergency call via 112 and decision of the emergency control centre; take-off about two minutes after the alert; any place in Luxembourg in about ten minutes; emergency doctor and intensive care nurse on board; road and leisure accidents, strokes; transfers between hospitals; hoist rescue; safety rules near a landing helicopter); \"Patient repatriation – Aircraft\" (call to the alert centre, doctor-to-doctor consultation, means of transport, costs covered for members); \"International collaborations\" (humanitarian missions with the Ministry of Foreign and European Affairs, official partner of the UN and NATO, organ transport for transplant centres in France); \"LAR Academy\"; \"Guided tours\"; \"Become a member\" and its FAQ (not an insurer; helicopters sent by the emergency services when they are the most effective help; card not needed; fee not tax-deductible, donations through the Luxembourg Air Rescue Foundation); \"Single membership\", \"Family membership\", \"Terms and conditions\" (cover one month after the first fee; stays abroad of up to 100 consecutive days, except for young people; exclusions; countries at war or in unrest; residence; the helicopter service benefits members and non-members); FAQ (LAR also carries out rescue missions for non-members). Durable wording only: no fees, no telephone numbers, no opening hours, no names, no exact numbers of members, missions or aircraft (the site gives about 185,000 members). The lists of countries of residence differ between the pages of the site, so only France, Belgium and Germany are named. The opening scene and the hosts' advice to save the alert centre's number before travelling are illustrations by the hosts. General information only. Accurate as of November 2026.*",
 "fr": "*Sources : lar.lu (Luxembourg Air Rescue A.s.b.l.), consulté le 26 novembre 2026 en anglais, avec les pages d'accueil française et allemande et la FAQ française « Devenir membre » pour les termes officiels — page d'accueil ; « À propos de nous » (association sans but lucratif fondée en 1988 par un groupe de pompiers ; organisation privée d'utilité publique ; centre d'alerte jour et nuit) ; « Historique » (accords avec la Sarre et la Rhénanie-Palatinat ; entraînements au treuil avec les services d'incendie et de secours) ; « Sauvetage aérien – Hélicoptères » (appel au 112 et décision du central des secours ; décollage environ deux minutes après l'alerte ; tout le pays en dix minutes environ ; médecin urgentiste et infirmier en soins intensifs à bord ; accidents de la route et de loisirs, AVC ; transferts entre hôpitaux ; sauvetage au treuil ; règles de sécurité près d'un hélicoptère) ; « Rapatriement de patients – Avions » (centre d'alerte, échange entre médecins, moyens de transport, frais pris en charge pour les membres) ; « Collaborations internationales » (missions humanitaires avec le ministère des Affaires étrangères et européennes, partenaire officiel de l'ONU et de l'OTAN, transport d'organes en France) ; « LAR Academy » ; « Visites guidées » ; « Devenir membre » et sa FAQ (pas une assurance ; hélicoptères envoyés par les secours quand ils sont le moyen le plus efficace ; carte pas nécessaire ; cotisation non déductible, dons via la Fondation Luxembourg Air Rescue) ; « Affiliation individuelle », « Affiliation familiale », « Conditions générales » (couverture un mois après la première cotisation ; séjours de 100 jours consécutifs au plus, sauf pour les jeunes ; exclusions ; pays en guerre ou en troubles ; résidence ; le service d'hélicoptères profite aux membres et aux non-membres). Formulations durables uniquement : pas de montants, pas de numéros de téléphone, pas d'horaires, pas de noms, pas de nombres exacts de membres, de missions ou d'appareils. Les listes de pays de résidence diffèrent d'une page à l'autre du site ; seuls la France, la Belgique et l'Allemagne sont donc nommées. La scène d'ouverture et le conseil d'enregistrer le numéro du centre d'alerte sont des illustrations des animateurs. Informations générales uniquement. Exact en novembre 2026.*",
 "de": "*Quellen: lar.lu (Luxembourg Air Rescue A.s.b.l.), abgerufen am 26. November 2026 auf Englisch, mit der französischen und der deutschen Startseite und den französischen FAQ „Mitglied werden“ für die offiziellen Begriffe — Startseite; „Über uns“ (gemeinnütziger Verein, 1988 von einer Gruppe von Feuerwehrleuten gegründet; private Organisation des öffentlichen Nutzens; Alarmzentrale rund um die Uhr); „Geschichte“ (Vereinbarungen mit dem Saarland und Rheinland-Pfalz; Windentraining mit den Feuerwehr- und Rettungsdiensten); „Luftrettung – Hubschrauber“ (Notruf 112 und Entscheidung der Notrufzentrale; Start etwa zwei Minuten nach der Alarmierung; jeder Ort in Luxemburg in etwa zehn Minuten; Notarzt und Intensivpflegekraft an Bord; Verkehrs- und Freizeitunfälle, Schlaganfälle; Verlegungen zwischen Krankenhäusern; Windenrettung; Sicherheitsregeln bei einer Landung); „Rückführung von Patienten – Flugzeuge“ (Alarmzentrale, Gespräch zwischen den Ärzten, Transportmittel, Kosten für Mitglieder übernommen); „Internationale Kooperationen“ (humanitäre Einsätze mit dem Ministerium für auswärtige und europäische Angelegenheiten, offizieller Partner der UNO und der NATO, Organtransporte in Frankreich); „LAR Academy“; „Führungen“; „Mitglied werden“ mit FAQ (keine Versicherung; Hubschrauber werden von den Rettungsdiensten geschickt, wenn sie die wirksamste Hilfe sind; Karte nicht nötig; Beitrag nicht absetzbar, Spenden über die Stiftung Luxembourg Air Rescue); „Einzelmitgliedschaft“, „Familienmitgliedschaft“, „Allgemeine Geschäftsbedingungen“ (Schutz einen Monat nach dem ersten Beitrag; Aufenthalte von höchstens 100 aufeinanderfolgenden Tagen, außer für junge Menschen; Ausschlüsse; Länder im Krieg oder mit Unruhen; Wohnsitz; der Hubschrauberdienst kommt Mitgliedern und Nichtmitgliedern zugute). Nur dauerhafte Angaben: keine Beträge, keine Telefonnummern, keine Öffnungszeiten, keine Namen, keine genauen Zahlen zu Mitgliedern, Einsätzen oder Flugzeugen. Die Listen der Wohnsitzländer unterscheiden sich zwischen den Seiten der Website; deshalb werden nur Frankreich, Belgien und Deutschland genannt. Die Eingangsszene und der Rat, die Nummer der Alarmzentrale vor der Reise zu speichern, sind Veranschaulichungen der Moderatoren. Nur allgemeine Informationen. Stand: November 2026.*",
 "lb": "*Quellen: lar.lu (Luxembourg Air Rescue A.s.b.l.), consultéiert de 26. November 2026 op Englesch, mat der franséischer an der däitscher Startsäit an de franséischen FAQ „Devenir membre“. Fräi Iwwersetzung: de Site huet keng lëtzebuergesch Versioun. Keng Beträg, keng Telefonsnummeren, keng Ëffnungszäiten, keng Nimm a keng genau Zuelen. Nëmmen allgemeng Informatiounen. Stand: November 2026.*",
}
def turns(path):
    return [l.rstrip("\n") for l in open(path, encoding="utf-8") if l.startswith("**ANNA") or l.startswith("**TOM")]
for lang in ("en", "fr", "de", "lb"):
    sfx = "" if lang == "en" else "_" + lang
    ref = turns(f"podcast_script_kjt{sfx}.md")
    intro, closing, last2 = ref[:3], ref[-3], ref[-2:]
    outro = closing[closing.index(OUTRO_START[lang]):]
    body = []
    for l in open(f"build/lar_src/{lang}.txt", encoding="utf-8"):
        l = l.strip()
        if not l: continue
        who, txt = l.split(": ", 1)
        assert who in ("A", "T", "C"), l[:30]
        if who == "C": txt += " " + outro
        body.append(f"**{'TOM' if who == 'T' else 'ANNA'}:** {txt}")
    assert len(body) == 48, (lang, len(body))
    seq = [x[2] for x in intro + body + last2]
    assert all(a != b for a, b in zip(seq, seq[1:])), (lang, "same speaker twice")
    head = [h.replace("{MIN}", str(MIN[lang])) for h in HEAD[lang]]
    out = "\n".join([head[0], "", *head[1:], "", "---", "", *intro, *body, *last2, "", "---", "", SOURCES[lang], ""])
    open(f"podcast_script_{KEY}{sfx}.md", "w", encoding="utf-8").write(out)
    t = turns(f"podcast_script_{KEY}{sfx}.md")
    print(lang, len(t), "turns;", "..." in out or "…" in out, "ellipsis;", sum(len(x.split(":** ",1)[1]) for x in t), "chars")
